17:   function rngFactory(seed){let s=seed>>>0;return ()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}
18:   function generateFloor(){
19:     const rand=rngFactory(87321+state.floor*907+state.run*151), map=Array.from({length:SIZE},()=>Array(SIZE).fill(T.WALL));
20:     const rooms=[];
