27:     }
28:     if(rooms.length<2){for(let y=2;y<16;y++)for(let x=2;x<16;x++)map[y][x]=T.FLOOR;rooms.push({x:2,y:2,w:12,h:12})}
29:     const center=r=>({x:Math.floor(r.x+r.w/2),y:Math.floor(r.y+r.h/2)});
30:     state.player=center(rooms[0]);state.stairs=center(rooms[rooms.length-1]);map[state.stairs.y][state.stairs.x]=T.STAIR;
31:     state.enemies=[];state.items=[];state.chests=[];state.seen=new Set();state.visible=new Set();state.shrine=null;
32:     const used=new Set([`${state.player.x},${state.player.y}`,`${state.stairs.x},${state.stairs.y}`]);
33:     function placeInRoom(room,kind){const cells=[];for(let y=room.y;y<room.y+room.h;y++)for(let x=room.x;x<room.x+room.w;x++)if(map[y][x]===T.FLOOR&&!used.has(`${x},${y}`))cells.push({x,y});if(!cells.length)return null;const p=cells[Math.floor(rand()*cells.length)];used.add(`${p.x},${p.y}`);if(kind==='chest')map[p.y][p.x]=T.CHEST;if(kind==='shrine')map[p.y][p.x]=T.SHRINE;return p}
34:     const monsterTypes= state.floor===1?['그림자 쥐','잿빛 망령','길 잃은 기사']:['심연의 망령','그림자 쥐','봉인된 기사'];
35:     rooms.slice(1).forEach((room,i)=>{if(rand()<.88){const p=placeInRoom(room);if(p)state.enemies.push({x:p.x,y:p.y,name:monsterTypes[Math.floor(rand()*monsterTypes.length)],hp:state.floor===1?5+Math.floor(rand()*3):7+Math.floor(rand()*4),maxHp:8,damage:2+Math.floor(rand()*3),awake:false,kind:rand()<.22?'elite':'normal'})}if(i>0&&rand()<.46){const p=placeInRoom(room,'chest');if(p)state.chests.push(p)}if(i===1&&rand()<.8){const p=placeInRoom(room,'shrine');if(p)state.shrine=p}});
