40:   function key(x,y){return `${x},${y}`}
41:   function inBounds(x,y){return x>=0&&y>=0&&x<SIZE&&y<SIZE}
42:   function enemyAt(x,y){return state.enemies.find(e=>e.x===x&&e.y===y)}
43:   function isWalkable(x,y){return inBounds(x,y)&&![T.WALL,T.WATER].includes(state.map[y][x])&&!enemyAt(x,y)}
44:   function updateVisibility(){state.visible.clear();for(let dy=-5;dy<=5;dy++)for(let dx=-5;dx<=5;dx++){if(dx*dx+dy*dy>30)continue;const x=state.player.x+dx,y=state.player.y+dy;if(!inBounds(x,y))continue;state.visible.add(key(x,y));state.seen.add(key(x,y))}}
45:   function tileColors(x,y){const n=(x*13+y*23)%5;return ['#33342d','#35362e','#30322c','#38382f','#32342e'][n]}
46:   function draw(){
