48:     for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++){
49:       const k=key(x,y),tile=state.map[y][x],known=state.seen.has(k),visible=state.visible.has(k),px=x*TILE,py=y*TILE;
50:       if(!known)continue;
51:       const base=tile===T.WALL?'#1a1b18':tileColors(x,y);ctx.fillStyle=base;ctx.fillRect(px,py,TILE,TILE);
52:       if(tile===T.WALL){ctx.fillStyle='#23241f';ctx.fillRect(px+1,py+1,TILE-2,TILE-3);ctx.fillStyle='#151612';ctx.fillRect(px+1,py+TILE-4,TILE-2,3);ctx.fillStyle='#292a24';ctx.fillRect(px+3,py+3,2,2);if((x+y)%3===0){ctx.strokeStyle='#30312a';ctx.beginPath();ctx.moveTo(px+TILE-4,py+4);ctx.lineTo(px+TILE-4,py+TILE-5);ctx.stroke()}}
53:       else{ctx.fillStyle='#272923';ctx.fillRect(px+1,py+1,TILE-2,TILE-2);ctx.fillStyle='#424238';ctx.fillRect(px+3,py+3,1,1);if((x*7+y*5)%4===0){ctx.fillStyle='#4b4a3c';ctx.fillRect(px+TILE-5,py+TILE-6,2,1)}}
54:       if(tile===T.STAIR){ctx.fillStyle='#c2ab69';ctx.globalAlpha=.7;ctx.beginPath();ctx.arc(px+TILE/2,py+TILE/2,8,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#ead494';ctx.lineWidth=1.5;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(px+8,py+10+i*4);ctx.lineTo(px+TILE-8,py+10+i*4);ctx.stroke()}ctx.fillStyle='#fff0bb';ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText('↓',px+TILE/2,py+TILE/2+3)}
55:       if(tile===T.CHEST){ctx.fillStyle='#906c3c';ctx.fillRect(px+8,py+12,16,12);ctx.fillStyle='#bd9957';ctx.fillRect(px+8,py+12,16,4);ctx.fillStyle='#d5bc77';ctx.fillRect(px+15,py+16,3,4);ctx.fillStyle='#533d28';ctx.fillRect(px+7,py+23,18,2)}
56:       if(tile===T.SHRINE){ctx.fillStyle='#685d3c';ctx.fillRect(px+14,py+14,4,10);ctx.fillStyle='#d3bd79';ctx.beginPath();ctx.arc(px+TILE/2,py+12,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffedb4';ctx.beginPath();ctx.arc(px+TILE/2,py+12,2,0,Math.PI*2);ctx.fill()}
57:       if(tile===T.DOOR){ctx.fillStyle='#70583b';ctx.fillRect(px+9,py+5,14,24);ctx.fillStyle='#c1a265';ctx.fillRect(px+10,py+6,12,22);ctx.fillStyle='#59452e';ctx.fillRect(px+12,py+8,8,18);ctx.fillStyle='#e8cc80';ctx.fillRect(px+18,py+18,2,2)}
58:       if(tile===T.RUBBLE){ctx.fillStyle='#8c8a77';ctx.fillRect(px+9,py+18,4,4);ctx.fillRect(px+16,py+14,5,4);ctx.fillRect(px+14,py+22,6,3)}
59:       const enemy=enemyAt(x,y);if(enemy&&visible)drawEnemy(px,py,enemy);
60:       if(x===state.player.x&&y===state.player.y)drawPlayer(px,py);
61:       if(!visible){ctx.fillStyle='rgba(5,6,6,.58)';ctx.fillRect(px,py,TILE,TILE)}
62:       if(visible){ctx.strokeStyle='rgba(12,13,11,.38)';ctx.lineWidth=.6;ctx.strokeRect(px+.3,py+.3,TILE-.6,TILE-.6)}
63:     }
64:     updateUI();
65:   }
66:   function drawPlayer(x,y){ctx.fillStyle='#c9a95e';ctx.globalAlpha=.25;ctx.beginPath();ctx.arc(x+TILE/2,y+TILE/2,13,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#4e4230';ctx.beginPath();ctx.moveTo(x+10,y+24);ctx.lineTo(x+14,y+11);ctx.lineTo(x+18,y+9);ctx.lineTo(x+22,y+13);ctx.lineTo(x+25,y+25);ctx.fill();ctx.fillStyle='#d4c49d';ctx.beginPath();ctx.arc(x+18,y+11,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#94876c';ctx.fillRect(x+12,y+15,12,10);ctx.fillStyle='#e5cb83';ctx.fillRect(x+17,y+14,2,4);ctx.fillStyle='#eee4c6';ctx.fillRect(x+19,y+10,2,2)}
67:   function drawEnemy(x,y,e){const elite=e.kind==='elite';ctx.fillStyle=elite?'rgba(181,93,69,.19)':'rgba(170,170,145,.13)';ctx.beginPath();ctx.arc(x+TILE/2,y+TILE/2,12,0,Math.PI*2);ctx.fill();if(e.name.includes('쥐')){ctx.fillStyle='#96907e';ctx.beginPath();ctx.ellipse(x+18,y+19,7,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d8b27f';ctx.beginPath();ctx.arc(x+24,y+18,3.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b84e46';ctx.fillRect(x+25,y+17,2,2);ctx.beginPath();ctx.moveTo(x+12,y+16);ctx.lineTo(x+9,y+10);ctx.lineTo(x+16,y+14);ctx.fill()}else{ctx.fillStyle=elite?'#765148':'#71756e';ctx.beginPath();ctx.moveTo(x+9,y+26);ctx.lineTo(x+12,y+14);ctx.lineTo(x+14,y+10);ctx.lineTo(x+21,y+10);ctx.lineTo(x+25,y+17);ctx.lineTo(x+26,y+26);ctx.fill();ctx.fillStyle='#bfb59a';ctx.beginPath();ctx.arc(x+18,y+12,5,0,Math.PI*2);ctx.fill();ctx.fillStyle=elite?'#e77d5c':'#d7c89b';ctx.fillRect(x+15,y+12,2,2);ctx.fillRect(x+20,y+12,2,2);ctx.fillStyle='#9c8b65';ctx.fillRect(x+11,y+20,14,2)}if(e.hp<e.maxHp){ctx.fillStyle='#24241f';ctx.fillRect(x+8,y+5,20,3);ctx.fillStyle='#d27462';ctx.fillRect(x+8,y+5,20*e.hp/e.maxHp,3)}}
68:   function updateUI(){ui('hpText').textContent=`${state.hp} / ${state.maxHp}`;ui('hpBar').style.width=`${100*state.hp/state.maxHp}%`;ui('levelText').textContent=`Lv. ${state.level}`;const need=state.level*8;ui('xpText').textContent=`${state.xp} / ${need}`;ui('xpBar').style.width=`${100*state.xp/need}%`;ui('potionCount').textContent=state.potions;ui('mobilePotionCount').textContent=state.potions;ui('bombCount').textContent=state.bombs;ui('scrollCount').textContent=state.scrolls;ui('goldCount').textContent=state.gold;ui('turnText').textContent=`턴 ${state.turn}`;ui('positionText').textContent=`좌표 ${String(state.player.x+1).padStart(2,'0')}·${String(state.player.y+1).padStart(2,'0')}`;ui('floorNum').textContent=`층 ${String(state.floor).padStart(2,'0')}`;ui('runNum').textContent=String(state.run).padStart(2,'0');ui('enemyCount').textContent=state.enemies.filter(e=>state.visible.has(key(e.x,e.y))).length;const explored=state.seen.size/(SIZE*SIZE-36);const pct=Math.min(100,Math.round(explored*100));ui('questProgress').style.width=`${pct}%`;ui('questCount').textContent=`탐험 ${pct}%`;ui('objectiveTitle').textContent=state.floor>=3?'왕의 기억을 찾아라':'회랑을 통과하라';ui('objectiveText').textContent=state.floor>=3?'잊힌 왕국의 마지막 봉인을 찾아라.':'아래층으로 가는 계단을 찾아라.';ui('floorName').textContent=state.floor===1?'잊힌 회랑':state.floor===2?'속삭임의 납골당':'왕의 기억';}
69:   function damagePlayer(amount,source='적'){state.hp=Math.max(0,state.hp-amount);log(`${source}의 공격! 생명력 ${amount} 감소.`, 'warn');if(state.hp<=0)endRun(false)}
70:   function attack(enemy){const dmg=4+Math.floor(Math.random()*4)+(state.level-1)*2;enemy.hp-=dmg;state.turn++;log(`잿빛 검으로 ${enemy.name}을(를) 베었다. (${dmg})`, 'good');if(enemy.hp<=0){state.enemies=state.enemies.filter(e=>e!==enemy);state.xp+=enemy.kind==='elite'?5:3;state.gold+=enemy.kind==='elite'?5:2;state.kills++;log(`${enemy.name}을(를) 쓰러뜨렸다. 은화와 경험치를 얻었다.`, 'gold');checkLevel()}else{enemy.awake=true;enemyFlash()};enemyTurns();updateVisibility();draw()}
71:   function enemyFlash(){canvas.classList.remove('hit');void canvas.offsetWidth;canvas.classList.add('hit');setTimeout(()=>canvas.classList.remove('hit'),160)}
72:   function checkLevel(){if(state.xp>=state.level*8){state.xp-=state.level*8;state.level++;state.maxHp+=5;state.hp=Math.min(state.maxHp,state.hp+8);log(`레벨 상승! Lv. ${state.level} · 생명력이 회복되었다.`, 'gold');toast(`레벨 상승! Lv. ${state.level}`)}}
